import { createHmac, timingSafeEqual } from "node:crypto";
import { createWriteStream, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname, extname, join } from "node:path";

import { type AudioInput, type AudioOutput, PlayoutClock, pcmToSamples, samplesToPcm } from "../nur/audio.js";
import { EXPORT_FORMAT, fromPortable, InMemoryStore, Memory, type MemoryPolicy, type MemoryRecord, toPortable } from "../nur/memory/index.js";
import { INPUT_SAMPLE_RATE } from "../nur/protocol.js";
import { Trace, type TraceOptions } from "../nur/trace.js";

// ── memory ───────────────────────────────────────────────────────────────

/**
 * Records kept in one JSON file, in the portable form both SDKs export and
 * import. Every change rewrites the file through a temporary one, so a crash
 * never leaves half a file. Right for a game server's or a desktop app's
 * memory, up to tens of thousands of records; past that, implement
 * `MemoryStore` over your database.
 */
export class FileMemoryStore extends InMemoryStore {
    readonly path: string;
    private writing: Promise<void> = Promise.resolve();

    constructor(path: string) {
        super();
        this.path = path;
        let text: string | null = null;
        try {
            text = readFileSync(path, "utf8");
        } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
        if (text) {
            const data = JSON.parse(text) as { records?: Array<Record<string, unknown>> } | Array<Record<string, unknown>>;
            for (const item of Array.isArray(data) ? data : (data.records ?? [])) {
                const record = fromPortable(item);
                this.records.set(record.id, record);
            }
        }
    }

    override async put(record: MemoryRecord): Promise<void> {
        await super.put(record);
        await this.save();
    }

    override async delete(ids: string[]): Promise<number> {
        const count = await super.delete(ids);
        if (count) await this.save();
        return count;
    }

    override async touch(ids: string[], at: number): Promise<void> {
        await super.touch(ids, at);
        await this.save();
    }

    async close(): Promise<void> {
        await this.writing;
    }

    private save(): Promise<void> {
        const write = () => {
            mkdirSync(dirname(this.path), { recursive: true });
            const temporary = `${this.path}.${process.pid}.tmp`;
            writeFileSync(temporary, JSON.stringify({ format: EXPORT_FORMAT, version: 1, records: this.all().map(toPortable) }));
            renameSync(temporary, this.path);
        };
        this.writing = this.writing.then(write, write);
        return this.writing;
    }
}

/** A character's memory in a JSON file: a path ending in `.json`, or a directory to keep `memory.json` in. */
export function fileMemory(path = ".eesi/memory", policy: MemoryPolicy = {}, namespace = "default"): Memory {
    const file = extname(path) === ".json" ? path : join(path, "memory.json");
    return new Memory(new FileMemoryStore(file), policy, namespace);
}

// ── traces ───────────────────────────────────────────────────────────────

/** A trace appended to a JSONL file. */
export function fileTrace(path: string, options: Omit<TraceOptions, "onClose"> = {}): Trace {
    mkdirSync(dirname(path), { recursive: true });
    const stream = createWriteStream(path, { flags: "a" });
    return new Trace((line) => stream.write(`${line}\n`), { ...options, onClose: () => stream.end() });
}

// ── WAV files ────────────────────────────────────────────────────────────

export interface WavAudio {
    sampleRate: number;
    /** 16-bit mono PCM (several channels are averaged). */
    pcm: Uint8Array;
}

/** A 16-bit PCM WAV file's audio, as mono. */
export function readWav(path: string): WavAudio {
    const bytes = readFileSync(path);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const tag = (offset: number) => String.fromCharCode(...bytes.subarray(offset, offset + 4));
    if (bytes.byteLength < 12 || tag(0) !== "RIFF" || tag(8) !== "WAVE") throw new Error(`${path} is not a WAV file.`);
    let offset = 12;
    let channels = 1;
    let sampleRate = 0;
    let bits = 0;
    let data: Uint8Array | null = null;
    while (offset + 8 <= bytes.byteLength) {
        const id = tag(offset);
        const size = view.getUint32(offset + 4, true);
        const body = offset + 8;
        if (id === "fmt ") {
            const format = view.getUint16(body, true);
            channels = view.getUint16(body + 2, true);
            sampleRate = view.getUint32(body + 4, true);
            bits = view.getUint16(body + 14, true);
            if ((format !== 1 && format !== 0xfffe) || bits !== 16) throw new Error(`${path} must be 16-bit PCM (it is format ${format}, ${bits}-bit).`);
        } else if (id === "data") {
            data = bytes.subarray(body, Math.min(bytes.byteLength, body + size));
        }
        offset = body + size + (size % 2);
    }
    if (!data || !sampleRate) throw new Error(`${path} has no audio.`);
    const samples = pcmToSamples(data);
    if (channels === 1) return { sampleRate, pcm: samplesToPcm(samples) };
    const mono = new Int16Array(Math.floor(samples.length / channels));
    for (let frame = 0; frame < mono.length; frame += 1) {
        let sum = 0;
        for (let channel = 0; channel < channels; channel += 1) sum += samples[frame * channels + channel] as number;
        mono[frame] = Math.round(sum / channels);
    }
    return { sampleRate, pcm: samplesToPcm(mono) };
}

/** 16-bit mono PCM as WAV file bytes. */
export function wavBytes(pcm: Uint8Array, sampleRate: number): Uint8Array {
    const header = new DataView(new ArrayBuffer(44));
    const write = (offset: number, text: string) => [...text].forEach((char, index) => header.setUint8(offset + index, char.charCodeAt(0)));
    write(0, "RIFF");
    header.setUint32(4, 36 + pcm.byteLength, true);
    write(8, "WAVE");
    write(12, "fmt ");
    header.setUint32(16, 16, true);
    header.setUint16(20, 1, true);
    header.setUint16(22, 1, true);
    header.setUint32(24, sampleRate, true);
    header.setUint32(28, sampleRate * 2, true);
    header.setUint16(32, 2, true);
    header.setUint16(34, 16, true);
    write(36, "data");
    header.setUint32(40, pcm.byteLength, true);
    const out = new Uint8Array(44 + pcm.byteLength);
    out.set(new Uint8Array(header.buffer), 0);
    out.set(pcm, 44);
    return out;
}

/**
 * A WAV file as a microphone: played in real time in 20 ms frames, then
 * silence for as long as the session listens (a person who stopped talking).
 * `startAfterMs` waits before speaking, say for the character's greeting.
 */
export function wavInput(path: string, options: { startAfterMs?: number; realtime?: boolean } = {}): AudioInput {
    const { sampleRate, pcm } = readWav(path);
    const frameBytes = Math.round(sampleRate * 0.02) * 2;
    const silence = new Uint8Array(frameBytes);
    let closed = false;
    return {
        sampleRate,
        async *frames() {
            const realtime = options.realtime ?? true;
            const started = performance.now();
            let sent = 0;
            const pace = async () => {
                sent += 1;
                if (!realtime) return;
                const due = started + sent * 20;
                const wait = due - performance.now();
                if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait));
            };
            const lead = Math.round((options.startAfterMs ?? 0) / 20);
            for (let index = 0; index < lead && !closed; index += 1) {
                yield silence;
                await pace();
            }
            for (let offset = 0; offset < pcm.byteLength && !closed; offset += frameBytes) {
                yield pcm.subarray(offset, Math.min(pcm.byteLength, offset + frameBytes));
                await pace();
            }
            while (!closed) {
                yield silence;
                await pace();
            }
        },
        close() {
            closed = true;
        },
    };
}

/**
 * A speaker that records: what the character says is written to a WAV file
 * when the session closes, with the pauses between replies, and minus
 * whatever a barge-in cut before it would have played.
 */
export class WavRecorder implements AudioOutput {
    readonly sampleRate: number;
    private readonly clock: PlayoutClock;
    private chunks: Int16Array[] = [];
    private length = 0;
    private lastEnd = performance.now() / 1000;
    private written = false;

    constructor(
        readonly path: string,
        sampleRate = 24_000,
    ) {
        this.sampleRate = sampleRate;
        this.clock = new PlayoutClock(sampleRate);
    }

    play(pcm: Uint8Array): void {
        const samples = pcmToSamples(pcm);
        if (!samples.length) return;
        const now = performance.now() / 1000;
        if (this.clock.bufferedSeconds() === 0 && this.length > 0) {
            const gap = Math.round(Math.max(0, now - this.lastEnd) * this.sampleRate);
            if (gap) this.append(new Int16Array(gap));
        }
        this.append(samples);
        this.clock.push(samples.length);
        this.lastEnd = now + this.clock.bufferedSeconds();
    }

    flush(): void {
        let unplayed = Math.round(this.clock.bufferedSeconds() * this.sampleRate);
        while (unplayed > 0 && this.chunks.length) {
            const last = this.chunks[this.chunks.length - 1] as Int16Array;
            if (last.length <= unplayed) {
                this.chunks.pop();
                this.length -= last.length;
                unplayed -= last.length;
            } else {
                this.chunks[this.chunks.length - 1] = last.subarray(0, last.length - unplayed);
                this.length -= unplayed;
                unplayed = 0;
            }
        }
        this.clock.flush();
        this.lastEnd = performance.now() / 1000;
    }

    bufferedSeconds(): number {
        return this.clock.bufferedSeconds();
    }

    /** The recording so far, as 16-bit mono PCM. */
    pcm(): Uint8Array {
        const all = new Int16Array(this.length);
        let offset = 0;
        for (const chunk of this.chunks) {
            all.set(chunk, offset);
            offset += chunk.length;
        }
        return samplesToPcm(all);
    }

    close(): void {
        if (this.written) return;
        this.written = true;
        mkdirSync(dirname(this.path), { recursive: true });
        writeFileSync(this.path, wavBytes(this.pcm(), this.sampleRate));
    }

    private append(samples: Int16Array): void {
        this.chunks.push(samples);
        this.length += samples.length;
    }
}

// ── webhooks ─────────────────────────────────────────────────────────────

/** A webhook post whose signature or age does not check out. */
export class WebhookVerificationError extends Error {
    constructor(message: string) {
        super(message);
        this.name = "WebhookVerificationError";
    }
}

/** One post from a client secret's webhook: a reply, or the session's end. */
export interface WebhookEvent {
    id: string;
    type: "response.completed" | "session.ended" | string;
    created_at: number;
    session_id: string;
    metadata: Record<string, string>;
    response?: { id: string; status: string; text: string };
    reason?: string;
    duration_seconds?: number;
}

/**
 * Check a webhook post from a client secret's session and return its event.
 * `body` is the raw request body, exactly as received (not re-serialized
 * JSON); `headers` the request's headers. Throws `WebhookVerificationError`
 * when the `EESI-Signature` does not match or the post is older than
 * `toleranceSeconds` (a replay).
 *
 *     app.post("/nur", express.raw({ type: "application/json" }), (req, res) => {
 *         const event = verifyWebhook(req.body, req.headers, process.env.NUR_WEBHOOK_SECRET!);
 *         ...
 *     });
 */
export function verifyWebhook(
    body: string | Uint8Array,
    headers: Record<string, string | string[] | undefined> | Headers,
    secret: string,
    options: { toleranceSeconds?: number; now?: number } = {},
): WebhookEvent {
    const header = (name: string): string => {
        if (typeof (headers as Headers).get === "function") return (headers as Headers).get(name) ?? "";
        const found = Object.entries(headers as Record<string, string | string[] | undefined>).find(([key]) => key.toLowerCase() === name.toLowerCase())?.[1];
        return Array.isArray(found) ? (found[0] ?? "") : (found ?? "");
    };
    const raw = typeof body === "string" ? Buffer.from(body) : Buffer.from(body.buffer, body.byteOffset, body.byteLength);
    const id = header("eesi-webhook-id");
    const timestamp = Number(header("eesi-webhook-timestamp"));
    if (!Number.isInteger(timestamp)) throw new WebhookVerificationError("The webhook has no valid timestamp.");
    const now = options.now ?? Date.now() / 1000;
    if (Math.abs(now - timestamp) > (options.toleranceSeconds ?? 300)) throw new WebhookVerificationError("The webhook is too old (or from the future).");
    const expected = createHmac("sha256", secret).update(`${id}.${timestamp}.`).update(raw).digest();
    const given = header("eesi-signature")
        .split(",")
        .map((part) => part.trim())
        .filter((part) => part.startsWith("v1="))
        .map((part) => Buffer.from(part.slice(3), "hex"));
    if (!given.some((candidate) => candidate.length === expected.length && timingSafeEqual(candidate, expected))) {
        throw new WebhookVerificationError("The webhook signature does not match.");
    }
    const event = JSON.parse(raw.toString("utf8")) as WebhookEvent;
    if (event.id !== id) throw new WebhookVerificationError("The webhook body does not match its id.");
    return event;
}

export { INPUT_SAMPLE_RATE };
